using ForgeLine.Input;

namespace ForgeLine.Presentation;

internal readonly record struct GuidanceStep(string Key, PlayerGuidanceMilestone Milestone, string Objective, string Context, GameplayAction Action);

internal static class EarlyGameGuidanceCatalog
{
    internal static readonly GuidanceStep[] Steps =
    [
        new("starting-base", PlayerGuidanceMilestone.CommandCore, "UNDERSTAND YOUR STARTING BASE",
            "Your Command Core holds the starting construction materials and can provide nearby supply. Two Cargo Trucks are already available for regional deliveries; they are not mobile field-supply vehicles. Building a factory spends Core construction stock but does not fill that factory's production input inventory. Select your Core and inspect its local stock, then inspect a truck's actual cargo and separate drive tank. You can build and issue orders before reading any card. Success here only confirms your own completed Core. Starting Fuel, Ammunition and stocked providers do not prove that you have delivered materials, produced a vehicle or supplied a unit.", GameplayAction.Build),
        new("power", PlayerGuidanceMilestone.Power, "ESTABLISH POWER",
            "Industry needs usable power before work can progress. Open BUILD, choose Power Plant and place it at a valid site using your Command Core construction materials. A submitted build request is not a completed power station. Let construction finish and inspect the reported power state. This goal confirms an owned completed Power Plant that is actually generating. Existing factories may have different demand, so check the power summary as your base expands. If placement is rejected, follow its reported reason; if production reports NO POWER, inspect capacity and the facility's current power state rather than ordering another material shipment.", GameplayAction.Build),
        new("ore-extraction", PlayerGuidanceMilestone.FerrousExtraction, "EXTRACT FERROUS ORE",
            "Ferrous Ore feeds the Steel chain. Open BUILD, choose Mine / Extractor and use a valid Ferrous Ore deposit rather than an arbitrary empty site. Construction spends Core stock; extraction needs the completed building's own usable production conditions and finite deposit. Inspect the extractor's local output and its reported power or capacity state. This goal requires an actual positive extraction result from your own extractor, not merely a building, a displayed working label or starting Ore already in storage. Cargo Trucks can move available source surplus after a destination requests it. Keep output collection and power working so extraction can continue.", GameplayAction.Build),
        new("smelter", PlayerGuidanceMilestone.Smelter, "BUILD YOUR SMELTER",
            "A Smelter turns locally delivered Ferrous Ore into Steel. Open BUILD and construct it at a valid site with space for vehicles to approach and leave its loading bay. Nearby road access is registered through the existing building logistics rules; there is no separate guide-created route or free input stock. This goal confirms your own completed Smelter with its installed loading facility. Physical approach and bay access still need real transport feedback, so a completed building alone is not proof of a successful delivery. Inspect LOGISTICS next. If a route, approach or output is blocked, use its existing diagnosis rather than assuming a network node guarantees access.", GameplayAction.Build),
        new("smelter-policy", PlayerGuidanceMilestone.OrePolicy, "SUPPLY YOUR SMELTER",
            "Your Smelter needs Ferrous Ore in its own input inventory before it can produce Steel. Materials stored at the Command Core or a Mine are still at that location. Select the Smelter, open LOGISTICS and choose the Steel INPUTS card. USE INPUTS prepares the existing catalog-based policy editor; APPLY POLICY submits each required resource. New stock-threshold edits use 50-unit steps, while INPUTS additional steps count recipes, not truck loads. A confirmed stored Ore policy completes this configuration goal, not the delivery goal. Available Cargo Trucks collect suitable source stock automatically. Follow the reported loading, travel and unloading states. Once Ore actually arrives and power is available, the Smelter automatically processes Steel. Inspect the reported cause if the chain stops.", GameplayAction.Logistics),
        new("ore-delivery", PlayerGuidanceMilestone.OreDelivered, "FOLLOW THE ORE DELIVERY",
            "A saved stock policy asks regional distribution to replenish the selected building. Requested quantity is demand, not a fixed Cargo Truck batch; assigned incoming cargo is a promised load, not delivered stock. Select LOGISTICS ORDER pages to inspect request IDs, real states and waiting reasons; neither quantity is already inside your Smelter. Select the assigned Cargo Truck to inspect its real material, source, destination, loaded cargo and drive Fuel. Confirmed bay states distinguish queue waiting, alignment, loading, unloading and leaving. Ordinary FIFO waiting is not a transport failure. This goal requires a real positive Ore unload or conveyor delivery into your own Smelter. If no truck, stock or route is available, open the reported Operations entry and its existing controls. Do not repeatedly issue manual source and destination orders to every Cargo Truck.", GameplayAction.Logistics),
        new("steel", PlayerGuidanceMilestone.SteelProcessing, "PRODUCE STEEL AUTOMATICALLY",
            "After Ore has physically arrived, your powered Smelter automatically processes Steel. No recipe queue or PROCESS action is required. Recipe inputs come from the active catalog and the Smelter's own inventory; Core construction materials and incoming promises cannot substitute for local inputs. Reserved input is work in progress, not a completed cycle. This goal is confirmed only by an actual completed owned Steel cycle. If work reports NO INPUT, inspect the local free and reserved amounts and deliveries. If it reports NO POWER or OUTPUT FULL, address that reported condition through the existing facility and Operations controls.", GameplayAction.Logistics),
        new("factory", PlayerGuidanceMilestone.VehicleFactory, "BUILD VEHICLE FACTORY",
            "Use BUILD to construct a Vehicle Factory at a valid powered site with a usable loading approach. Construction consumes the Command Core's building materials. It does not copy those materials into the new factory's local production inventory. Your own completed factory confirms this construction goal; production readiness is a separate next goal. Select the factory and inspect LOGISTICS before queuing a vehicle. Check power as industry grows and leave room for Cargo deliveries and produced units to exit. Starting materials can help you build in another order, and the guide will observe your real completed actions even when this card is minimized or deferred.", GameplayAction.Build),
        new("factory-inputs", PlayerGuidanceMilestone.FactoryInputs, "PREPARE VEHICLE INPUTS",
            "Select your Vehicle Factory and open LOGISTICS. Choose the INPUTS card for Scout Vehicle, inspect the active catalog requirements and select the number of additional steps you want. USE INPUTS prepares a draft only. APPLY POLICY applies one resource at a time through the existing validated controls, preserving manual settings until you apply changes. MIN triggers replenishment, TARGET is the refill goal and MAX is saved policy metadata rather than a hard inventory limit. Shared storage capacity still applies. This goal confirms observed local Scout inputs; a real Scout completion also proves its inputs were supplied. New quantity edits move in 50-unit increments, independently of the 1-100 recipe additional-step counter. LOGISTICS ORDER pages show current request states; an accepted policy or assigned delivery alone is insufficient.", GameplayAction.Logistics),
        new("scout", PlayerGuidanceMilestone.Scout, "PRODUCE A SCOUT VEHICLE",
            "Select a supplied Vehicle Factory, open UNITS, choose Scout Vehicle and QUEUE. The current unit catalog defines its real local material costs, production duration and prerequisites; this guide does not maintain another cost table. Check accepted command feedback and the factory's production state. Queued work or an existing unit placed in a scene is not proof of production. This goal requires a Scout actually completed by your own unit production system. Keep input replenishment and power working for later vehicles. If the factory stops, use its reported reason and existing Logistics or Operations controls rather than assuming the guide supplies missing materials.", GameplayAction.Units),
        new("belt-production", PlayerGuidanceMilestone.ConveyorDelivery | PlayerGuidanceMilestone.ProductionOutput, "CONNECT BASE PRODUCTION",
            "Use BUILD to connect compatible building output and input ports with paid conveyors. Ferrous Ore, Silicates, Steel, Electronics and Ammunition can travel through connected powered belts. Until pipelines are built, Volatiles can enter a Refinery via an owned conveyor and its processed Fuel can leave by a second conveyor toward compatible local storage. A Refinery has one west INPUT and one east OUTPUT; both use the normal elevated belt height. The Fuel recipe still requires its real inputs and power. No physical pipelines or fluid pressure are simulated. Every belt segment holds finite material; a loaded belt is not a delivery into the next building. This goal needs a positive transfer into an owned building and actual completed processing output. Smelters and Electronics Fabricators process their local raw materials automatically when powered, and Refineries do the same for delivered Volatiles. Ammunition production still uses its existing recipe controls. Keep local inputs, power and output space available. Operations distinguishes disconnected ports, missing power, retained stock, damaged support and full output. Use TRACE NEXT, FOCUS FACILITY and OPEN EXISTING CONTROLS to inspect the observed cause. Leave vehicle dock approaches clear: regional Cargo Trucks still transport Fuel and Volatiles independently of local belts. Belts and trucks share finite building stock and destination targets; neither creates material.", GameplayAction.Build),
        new("research", PlayerGuidanceMilestone.ResearchCompleted, "CHOOSE A PAID RESEARCH INVESTMENT",
            "Open TECHNOLOGY to inspect the active catalog costs, prerequisites, required facility and current research state. Compare that investment with the materials needed to keep industry, replacement transports and defense working. Start research deliberately through the existing controls. A request can wait for materials, a completed facility or usable power; queued or paid work is not a completed technology. Costs are consumed when research starts, and cancelling does not refund them. This goal confirms actual owned research completion. Check the current capability and production requirements before planning a later unit. Reading this explanation grants no research, unlock or material and does not promise effects beyond the current catalog and implemented controls.", GameplayAction.Technology),
        new("truck-roles", PlayerGuidanceMilestone.None, "UNDERSTAND YOUR TWO TRUCK ROLES",
            "Cargo Trucks move resources between buildings, including Fuel and Volatiles, while compatible local base belts temporarily also move those two materials to and from Refineries. Trucks still connect distant industry and the front; there are no pipelines yet. You manage these deliveries with stock policies at the destination; available trucks receive transport work automatically. Supply Trucks carry Fuel and Ammunition to your forces. They load from a suitable stocked Supply Depot or Command Core. Keep depots supplied through the regional logistics network, then position loaded Supply Trucks where your units need support. Each vehicle also needs its own Fuel to drive. Fuel carried as cargo is separate from propulsion Fuel, so inspect both when a loaded truck cannot move. This explanation has no delivery achievement; reading it never creates a truck, material or supply transfer.", GameplayAction.Supply),
        new("depot", PlayerGuidanceMilestone.SupplyDepot | PlayerGuidanceMilestone.DepotFuelDelivered | PlayerGuidanceMilestone.DepotAmmunitionDelivered, "BUILD AND STOCK A SUPPLY DEPOT",
            "Build a Supply Depot at a valid site and leave its loading approach and exit clear. Construction uses Core building stock; the new depot still needs its own Fuel and Ammunition. Select it, open LOGISTICS and apply suitable policies for both resources using the existing stock controls. Cargo Trucks perform the regional deliveries. Watch requested and incoming quantities separately from local stock, then inspect confirmed unloading. This goal needs your own completed depot and real Fuel and Ammunition deliveries to owned depots; Ammunition may arrive by belt, while Fuel uses Cargo Trucks. A stocked Command Core at match start does not complete this lesson. Keep replenishment running as mobile providers consume depot stock.", GameplayAction.Build),
        new("supply-truck", PlayerGuidanceMilestone.SupplyTruckProduced, "PRODUCE A SUPPLY TRUCK",
            "A mobile Supply Truck must be produced through your Vehicle Factory; the starting Cargo Trucks cannot take its field-supply role. Select the factory, open LOGISTICS and use the Supply Truck INPUTS card to prepare the active catalog requirements. Apply each needed resource and wait for actual local availability. Then open UNITS, choose Supply Truck and QUEUE. Success requires an actual owned production completion, not a preplaced truck or an accepted request. Inspect blocked work through the existing controls. The new truck's drive tank and its field cargo remain different inventories, so producing it alone does not prove it has loaded depot supplies.", GameplayAction.Units),
        new("mobile-loading", PlayerGuidanceMilestone.SupplyTruckLoaded, "LOAD AND DELIVER FIELD SUPPLY",
            "Keep your Supply Depot stocked with Fuel and Ammunition. Move a Supply Truck near that depot so it is the nearest eligible loading building. Select the truck, open SUPPLY, choose REQUEST RESUPPLY and activate REQUEST SUPPLY. This existing action selects a suitable nearby building; it is not a manual source picker. The truck joins the reported loading queue and aligns before transfer is allowed. Inspect actual cargo increases and its separate drive tank. This goal needs real Fuel and Ammunition loads at the same depot visit. An assigned order, a nearby truck or a briefly displayed LOADING state alone is insufficient.", GameplayAction.Supply),
        new("field-supply", PlayerGuidanceMilestone.FieldSupplied, "RESUPPLY YOUR FORCES",
            "Move a loaded Supply Truck where it can actually serve your own forces. Select a unit and open SUPPLY to inspect its Fuel, Ammunition and automatic resupply thresholds. Choose REQUEST RESUPPLY and REQUEST SUPPLY when an explicit request is needed, or apply automatic settings through APPLY AUTO. A provider assignment does not instantly replenish the recipient. This goal requires an actual positive transfer from your mobile Supply Truck to an owned recipient. Observe the separate cargo and recipient amounts. If service is unavailable, inspect the existing provider and rejection reasons. Range, usable provider stock, movement and the recipient's actual need still govern every transfer.", GameplayAction.Supply),
        new("recovery", PlayerGuidanceMilestone.DisruptionResolved, "RECOVER A BLOCKED CHAIN",
            "Open Operations from the resource/power strip or a relevant OPS alert when a real chain reports a problem. Choose the relevant category or BLOCKED, select its entry and use FOCUS FACILITY and OPEN EXISTING CONTROLS. Follow the copied authoritative diagnosis: a missing source surplus differs from no suitable Cargo Truck, graph capacity differs from a bay queue, and a blocked approach differs from missing power or full storage. For example, an Ammunition Plant waiting for Electronics can lead through TRACE NEXT to an Electronics Plant missing Silicates. Follow only current observed connections; a branch, cycle or omitted observation is not a unique root-cause claim. Use FOCUS FACILITY and OPEN EXISTING CONTROLS at the observed source, restore its real input or connection, then recheck for any remaining power or capacity reason. Focus navigation submits no world order. Repair the actual cause through existing production, stock, supply or movement controls. This goal confirms observed blocked owned work returning to running work. For an owned processing building, RULES opens an explicit local draft. Smelters, Refineries and Electronics Fabricators process automatically; other processing buildings use their recipe orders. Choose INPUT STOCK POLICY, select its real input, set quantities and APPLY to install an absent policy after a shortage. This is not a delivery. Choose OUTPUT RECOVERY and APPLY to pause a full-output request and resume only after real space returns. DETAILS shows actual rule status; manual pauses and disabled stock policies still win. Reading a hint, cancelling a row or hiding a warning does not fabricate recovery.", GameplayAction.Logistics),
        new("contact", PlayerGuidanceMilestone.OpponentContact, "SCOUT THE OPPONENT",
            "Use your supplied Scout to explore and obtain permitted information about the opponent. Movement and combat remain under the normal controls; no guide step is required before issuing orders. This goal uses current faction-authorized contact evidence and does not expose hidden enemy inventories, units or positions. Protect known supply routes: escort exposed trucks with a ready group, reroute around an observed attack, and keep reserve transport capacity at home. Identified trucks, depots, power and production can be raid targets. A last-known contact is not a currently visible target, and a quiet route is not a safety guarantee. Keep the Scout's drive Fuel and field supply in mind as it travels. A detected opaque contact can confirm scouting without revealing its identity. If movement or supply fails, inspect the appropriate existing controls and return to the logistics explanations whenever useful. The guide observes progress independently from whether its cards have been read.", GameplayAction.Combat),
        new("victory", PlayerGuidanceMilestone.None, "CONTINUE YOUR MATCH",
            "You now have explanations for the complete opening production and supply chain. Keep extraction, Steel processing, vehicle inputs, depot replenishment and mobile field supply working as your forces expand. Later production may require additional material chains from the active catalog; starting stock is finite and cannot replace continuous supply. Use Operations to distinguish real shortages and blocked access from orderly bay queues. Revisit any card without changing world state or losing command access. Victory and defeat remain the authoritative match result, not a tutorial checkbox. This final explanation never forces the match to finish or grants material, units, routes or completed objectives.", GameplayAction.Combat),
    ];
}
